+/*
+  둘째·셋째 칸도 첫 칸과 같은 틀이다: 한쪽에 제목·설명·버튼, 다른 쪽에 서비스 화면을 담은 창.
+  셋째 칸은 창과 글의 자리를 바꿔 내려가는 동안 시선이 좌우로 오가게 한다.
+*/
+/*
+  글 칸은 내용 폭만큼만 잡고 창과 함께 가운데로 모은다. 두 칸을 화면 양끝까지 벌렸더니 글과 창이
+  서로 다른 칸처럼 떨어져 보였다.
+*/
+.storyLayout {
+  z-index: 1;
+  /* 옆에서 밀려 들어오는 글이 칸 밖으로 삐져나오지 않게 가로만 자른다. */
+  overflow-x: clip;
+  grid-template-columns: auto minmax(0, 640px);
+  justify-content: center;
+  align-items: center;
+  gap: clamp(32px, 4.5vw, 72px);
+  width: min(100% - 2 * clamp(24px, 4vw, 68px), 1180px);
+  padding: clamp(48px, 8vh, 96px) 0;
+}
+
+.storyReverse {
+  grid-template-columns: minmax(0, 640px) auto;
+}
+
+.storyCopy {
+  display: flex;
+  align-items: flex-start;
+  flex-direction: column;
+  min-width: 0;
+  word-break: keep-all;
+}
+
+.storyCopy h2 {
+  margin: 0;
+  color: var(--landing-text);
+  font-size: clamp(2rem, 3.2vw, 3rem);
+  font-weight: 700;
+  letter-spacing: -0.045em;
+  line-height: 1.16;
+}
+
+.storyCopy h2 > span { display: block; }
+
+.storyCopy h2 em {
+  background: linear-gradient(100deg, #e8f8ed 5%, #85eea7 58%, #03c75a 112%);
+  background-clip: text;
+  color: transparent;
+  font-style: normal;
+}
+
+.storyWindow { min-width: 0; }
+
+.storySteps {
+  display: grid;
+  gap: 14px;
+  margin: 26px 0 0;
+  padding: 0;
+  list-style: none;
+}
+
+.storySteps li {
+  display: grid;
+  grid-template-columns: 26px minmax(0, 1fr);
+  align-items: baseline;
+  gap: 12px;
+  color: var(--landing-text);
+  font-size: clamp(0.95rem, 1.2vw, 1.08rem);
+  font-weight: 600;
+}
+
+.storySteps b {
+  display: grid;
+  width: 26px;
+  height: 26px;
+  place-items: center;
+  border-radius: 50%;
+  background: var(--thorp-accent-muted);
+  color: var(--landing-accent-soft);
+  font-size: 0.72rem;
+  font-weight: 700;
+  transform: translateY(-2px);
+}
+
+.storySteps small {
+  display: block;
+  margin-top: 2px;
+  color: var(--landing-muted);
+  font-size: 0.82em;
+  font-weight: 500;
+}
+
+/* 창 안에서는 흐르는 지표 띠를 창 폭에 맞춰 줄인다. */
