+.storyWindow .indicatorReading strong { font-size: 1.25rem; }
+
+.fieldPreview {
+  display: grid;
+  gap: 8px;
+  margin: 0;
+  padding: 14px;
+  list-style: none;
+}
+
+.fieldPreview li {
+  display: grid;
+  grid-template-columns: 84px minmax(0, 1fr) 60px;
+  align-items: center;
+  gap: 12px;
+  padding: 12px 14px;
+  border: 1px solid var(--thorp-line);
+  border-radius: var(--thorp-radius-inset, 8px);
+  background: var(--thorp-surface-muted);
+}
+
+.fieldPreview b { color: var(--landing-text); font-size: 0.82rem; }
+.fieldPreview span { overflow: hidden; color: var(--thorp-copy); font-size: 0.74rem; text-overflow: ellipsis; white-space: nowrap; }
